blocks.text:
/// Synchronous HTTP client for the JS tool bridge.
///
/// Primary transport is [SyncHttpBridge] — a pooled async `HttpClient` in a
/// worker isolate, served synchronously over native mailboxes (Java-bridge
/// performance profile: TLS handshake once, then connection reuse). Until
/// the bridge has booted (it must complete while the event loop is alive;
/// the CLI awaits it at startup), requests fall back to the curl subprocess
/// transport below.
///
/// Security/robustness properties of the curl fallback:
/// - Every request carries `--connect-timeout`/`--max-time` so a hung
///   endpoint cannot freeze the isolate inside a QuickJS callback forever.
/// - Headers and bodies travel in 0700-mode temp files (`-H @file`,
///   `--data-binary @file`), never in the process argument list — auth
///   tokens stay invisible to `ps` and large payloads cannot hit the OS
///   argv size limit (`E2BIG`).
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'sync_http_bridge.dart';
import 'sync_retry_policy.dart';

/// Response from a sync HTTP request.
class SyncHttpResponse {
  /// The HTTP status code (`0` when the transport failed).
  final int statusCode;

  /// The response body text (UTF-8 decoded).
  final String body;

  /// Response headers (case-insensitive names as sent); empty when the
  /// transport does not capture them (curl-staged helpers, older bridges).
  final Map<String, String> headers;

  /// The raw response bytes when the transport captured them (curl reads
  /// the response file verbatim); falls back to the UTF-8 encoding of
  /// [body] — lossy for non-UTF-8 payloads.
  final List<int> bodyBytes;

  /// Creates a response with [statusCode], [body], and optional [headers].
  SyncHttpResponse(this.statusCode, this.body,
      [this.headers = const <String, String>{}, List<int>? rawBytes])
      : bodyBytes = rawBytes ?? utf8.encode(body);

  /// Whether the request succeeded (2xx status code).
  bool get isOk => statusCode >= 200 && statusCode < 300;

  /// Whether the response is a redirect the caller must follow.
  bool get isRedirect => statusCode >= 300 && statusCode < 400;
}

/// Synchronous HTTP client: pooled-isolate transport with a curl fallback.
class SyncHttpClient {
  /// curl exit code for `--max-time` / `--connect-timeout` expiry.
  static const _curlExitTimedOut = 28;

  /// Connect-phase budget in seconds (mirrors the 10s reviewer ask; Java
  /// `JiraClient` allows 60s, but a hung TCP connect is worthless inside a
  /// frozen event loop, so the sync path fails fast).
  static const connectTimeoutSeconds = 10;

  /// Total request budget in seconds (connect + transfer), matching the Java
  /// client's 60s read timeout.
  static const maxTimeSeconds = 60;

  /// Performs a synchronous GET request.
  ///
  /// [followRedirects] opts into 3xx following (curl `-L` /
  /// `HttpClientRequest.followRedirects`); the default stays `false` for
  /// curl `-s` parity. Agent-pack downloads set it — Java's
  /// `AgentPackResolver` follows redirects, and GitHub Releases download
  /// URLs 302 to a signed CDN URL.
  static SyncHttpResponse get(
    String url, {
    Map<String, String>? headers,
    bool followRedirects = false,
  }) =>
      _dispatch('GET', url, headers: headers, followRedirects: followRedirects);

  /// Performs a synchronous POST request.
  static SyncHttpResponse post(
    String url, {
    Map<String, String>? headers,
    String? body,
  }) =>
      _dispatch('POST', url, headers: headers, body: body);

  /// Performs a synchronous PUT request.
  static SyncHttpResponse put(
    String url, {
    Map<String, String>? headers,
    String? body,
  }) =>
      _dispatch('PUT', url, headers: headers, body: body);

  /// Performs a synchronous DELETE request.
  static SyncHttpResponse delete(String url, {Map<String, String>? headers}) =>
      _dispatch('DELETE', url, headers: headers);

  /// Performs a synchronous PATCH request (GitHub issue state updates).
  static SyncHttpResponse patch(
    String url, {
    Map<String, String>? headers,
    String? body,
  }) =>
      _dispatch('PATCH', url, headers: headers, body: body);

  /// Routes a request through the pooled-isolate bridge when booted, the
  /// curl subprocess otherwise, retrying retryable failures per
  /// [SyncRetryPolicy.forUrl] (gh-191, P6-JSY-18: Java `JiraClient.execute`
  /// retries 429/502/503/504 and connection errors with backoff).
  /// Public dispatch used by the `fetch` compat transport (engine_factory);
  /// the verb-specific statics delegate here.
  static SyncHttpResponse dispatch(
    String method,
    String url, {
    Map<String, String>? headers,
    String? body,
    bool followRedirects = false,
  }) =>
      _dispatch(method, url,
          headers: headers, body: body, followRedirects: followRedirects);

  static SyncHttpResponse _dispatch(
    String method,
    String url, {
    Map<String, String>? headers,
    String? body,
    bool followRedirects = false,
  }) {
    final policy = SyncRetryPolicy.forUrl(url);
    // Java `isWaitBeforePerform` throttle before the request goes out.
    final performDelay = policy.performDelayMs;
    if (performDelay > 0) sleep(Duration(milliseconds: performDelay));
    var attempt = 1;
    while (true) {
      final resp = _transport(method, url,
          headers: headers, body: body, followRedirects: followRedirects);
      if (!policy.shouldRetry(attempt, resp.statusCode)) return resp;
      final delayMs = resp.statusCode == 0
          ? policy.connectionDelayMs(attempt)
          : policy.statusDelayMs(attempt, resp.headers, resp.statusCode);
      if (delayMs == null) {
        return resp; // non-rate-limit Retry-After over the cap: give up
      }
      sleep(Duration(milliseconds: delayMs));
      attempt++;
