```java
long retryAfterSeconds = Long.parseLong(retryAfter);
boolean rateLimited = response.code() == 429;
if (!rateLimited && retryAfterSeconds > MAX_RETRY_AFTER_SECONDS) {
    throw new IOException(...);  // abort
