    public static final long DEFAULT_MAX_DELAY_MS = 60000L; // 60 seconds
    public static final double DEFAULT_BACKOFF_MULTIPLIER = 2.0;
    public static final double DEFAULT_JITTER_FACTOR = 0.3; // 30% jitter

